import '../../../core/l10n/app_localizations.dart';

// These prefixes are generated by tierDetailsOf, not supplied by customers.
// Keep its raw format stable for pricing/spec parsers and translate only at
// display boundaries. Provider names, numeric amounts and currencies stay intact.
const _detailLabels = [
  'Monthly limit',
  'Transaction limit',
  'Daily free draws',
  'Cards used',
  'Daily limit',
  'ATM limit',
  'Max cards',
  'Benefit',
  'Feature',
  'Price',
  'Cycle',
  'Level',
  'Card',
  'KYC',
];

String localizeTierDetail(AppLocalizations l10n, String detail) {
  if (l10n.locale.languageCode == 'en') return detail;
  for (final label in _detailLabels) {
    if (detail.startsWith('$label ')) {
      final value = detail.substring(label.length + 1);
      return '${l10n.translate(label)} ${localizeTierDetailValue(l10n, label, value)}';
    }
  }
  // Only complete catalog matches are translated; arbitrary provider prose
  // is never changed through substring replacement.
  return l10n.translate(detail);
}

String localizeTierDetailValue(
    AppLocalizations l10n, String? label, String value) {
  if (l10n.locale.languageCode == 'en') return value;
  if (label == null) return localizeTierDetail(l10n, value);
  if (label == 'Cycle') {
    final key = switch (value.toLowerCase()) {
      'monthly' => 'Monthly',
      'yearly' || 'annual' || 'annually' => 'Yearly',
      'weekly' => 'Weekly',
      'daily' => 'Daily',
      _ => null,
    };
    return key == null ? value : l10n.translate(key);
  }
  if (label != 'Price' && label != 'Card') return value;
  final separator = value.contains(' • ') ? ' • ' : ' · ';
  final parts = value.split(separator);
  const prefixes = {
    'monthly': 'Monthly',
    'yearly': 'Yearly',
    'free cards': 'Cards included',
    'issue': 'Card issue fee',
    'replacement': 'Replacement fee',
    'count': 'Cards',
  };
  return [
    for (var index = 0; index < parts.length; index++)
      // The first card segment is a provider's product name.
      if (label == 'Card' && index == 0)
        parts[index]
      else
        _localizePart(l10n, parts[index], prefixes),
  ].join(separator);
}

String _localizePart(
    AppLocalizations l10n, String part, Map<String, String> prefixes) {
  for (final entry in prefixes.entries) {
    if (part.startsWith('${entry.key} ')) {
      return '${l10n.translate(entry.value)} ${part.substring(entry.key.length + 1)}';
    }
  }
  return part;
}
